// Merge candidates + history and prepare Gemini context
const candidates = $input.all().filter(i => i.json.object === 'page');
const history = $('Notion — Historique 4 semaines').all();

// Extract used recipe IDs from history
const usedIds = new Set();
history.forEach(h => {
  const recipes = h.json.properties?.Recettes_proposées?.relation || [];
  recipes.forEach(r => usedIds.add(r.id));
});

// Format candidates for Gemini
const candidateList = candidates.map(c => ({
  id: c.json.id,
  nom: c.json.properties?.Nom?.title?.[0]?.plain_text || '',
  categorie: c.json.properties?.Catégorie?.select?.name || '',
  jour_type: c.json.properties?.Jour_type?.select?.name || 'Semaine',
  duree_min: c.json.properties?.Durée_minutes?.number || 30,
  complexite: c.json.properties?.Complexité?.select?.name || 'Facile',
  fois_prepare: c.json.properties?.Fois_préparé?.number || 0,
  recemment_fait: usedIds.has(c.json.id)
})).filter(c => !c.recemment_fait);

// Determine current season
const month = new Date().getMonth() + 1;
const season = month >= 3 && month <= 5 ? 'printemps'
  : month >= 6 && month <= 8 ? 'été'
  : month >= 9 && month <= 11 ? 'automne'
  : 'hiver';

// ISO week
const now = new Date();
const startOfYear = new Date(now.getFullYear(), 0, 1);
const weekNo = Math.ceil(((now - startOfYear) / 86400000 + startOfYear.getDay() + 1) / 7);
const isoWeek = `${now.getFullYear()}-W${String(weekNo).padStart(2, '0')}`;

return [{
  json: {
    candidates: candidateList,
    season,
    current_date: new Date().toISOString().split('T')[0],
    iso_week: isoWeek,
    recent_history: history.map(h => h.json.properties?.Semaine?.title?.[0]?.plain_text || '').filter(Boolean)
  }
}];

