// Parse Gemini response and extract menu JSON
const raw = $input.first().json;
const text = raw.candidates?.[0]?.content?.parts?.[0]?.text || '';

// Strip potential markdown code blocks
const cleaned = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
const menu = JSON.parse(cleaned);

const jours = ['lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi', 'dimanche'];
const emoji = { lundi:'🥕', mardi:'🍝', mercredi:'🐟', jeudi:'🥗', vendredi:'🍗', samedi:'🍖', dimanche:'🥘' };

// Build Telegram message
let msg = `🍽️ *Menu de la semaine ${menu.semaine}*\n\n`;
jours.forEach(j => {
  const r = menu.menu[j];
  msg += `${emoji[j]} *${j.charAt(0).toUpperCase() + j.slice(1)}* : ${r.nom} (${r.duree_min} min)\n`;
});
msg += `\nValide chaque recette ou remplace-la :`;

// Build inline keyboard
const keyboard = jours.map(j => [
  { text: `✅ ${j.charAt(0).toUpperCase() + j.slice(1)}`, callback_data: `validate_day_${j}_${menu.menu[j].id}` },
  { text: `🔄`, callback_data: `replace_day_${j}` }
]);
keyboard.push([{ text: '✅ Tout valider', callback_data: 'validate_all' }]);

return [{ json: { menu, message: msg, keyboard, iso_week: menu.semaine } }];
